module heart_o2_top(
	rst,
	uart_rx_from_heart,
	spo_data,
	heart_data,
	uart_tx_to_heart,
	clk);

	//---Ports declearation: generated by Robei---
	input rst;
	input uart_rx_from_heart;
	output [7:0] spo_data;
	output [7:0] heart_data;
	output uart_tx_to_heart;
	input clk;

	wire rst;
	wire uart_rx_from_heart;
	reg [7:0] spo_data;
	reg [7:0] heart_data;
	wire uart_tx_to_heart;
	wire clk;

	//----Code starts here: integrated by Robei-----
	wire uart_tx_to_heart_wire;
	reg tx_sig_d1;
	reg tx_sig_d2;
	reg rx_en;
	wire rx_sig;
	wire tx_sig;
	wire pack_done;
	reg rx_sig_d1;
	reg rx_sig_d2;
	reg tx_go_flag;
	wire [7:0] dataA;
	wire [7:0] dataB;
	wire [7:0] dataC;
	wire [7:0] dataD;
	wire [7:0] dataE;
	wire [7:0] pack_num;
	wire [7:0] pack_cnt;
	wire [7:0]  uart_data;
	reg	[7:0]rx_dataA_reg;
	reg	[7:0]rx_dataB_reg;
	reg	[7:0]rx_dataC_reg;
	reg	[7:0]rx_dataD_reg;
	reg [7:0]type_flag;
	reg[39:0] delay_cnt1;
	reg[39:0] delay_cnt2;
	///////////////////////////////////////////////////////
	reg    [7:0]      cur_state;
	reg    [7:0]      next_state;
	///////////////////////////////////////////////////////
	parameter      SEND_HEART =   8'd4,
	                SEND_SPO = 8'd5,
	                WAIT_SPO=    8'd6,  
	                WAIT_HEART =8'd7,
	                WAIT_DELAY_SPO = 8'd8,
	                WAIT_DELAY_HEART = 8'd9;
	parameter		T_40MS = 31'd4000000,
	                T_6S = 'd10_000_000,
	                T_Delay1 = 'd100,
	                T_Delay2 = 'd150,
	                T_DAC1S = 'd33333333;
	////////////////////////////////////////////////////////
	
		 always @(posedge clk or negedge rst)begin
		 	if(!rst)
		 	begin
		 		rx_dataA_reg <= 8'd0;
		 		rx_dataB_reg <= 8'd0;
		 		rx_dataC_reg <= 8'd0;
		 		rx_dataD_reg <= 8'd0;
		 		delay_cnt1 <= 40'd0;  
		 		delay_cnt2 <= 40'd0;
		 	end
		 	else if(rx_sig_rise)
		 	begin
		 		rx_dataA_reg <= dataA;
		 		rx_dataB_reg <= dataB;
		 		rx_dataC_reg <= dataC;
		 		rx_dataD_reg <= dataD;
	        end        
		 	else
		 	begin
		 		rx_dataA_reg <= rx_dataA_reg;
		 		rx_dataB_reg <= rx_dataB_reg;
		 		rx_dataC_reg <= rx_dataC_reg;
		 		rx_dataD_reg <= rx_dataD_reg;	 		
	        end
		 end
		 
	     always @(posedge clk or negedge rst)begin
	        if(!rst) begin
	            rx_sig_d1 <= 1'd0;
	            rx_sig_d2 <= 1'd0;
	        end
	        else begin
	            rx_sig_d1 <= pack_done;
	            rx_sig_d2 <= rx_sig_d1;
	        end
	     end
		 
		 assign rx_sig_rise = ~rx_sig_d2 && rx_sig_d1;                 //接收完成标志
	////////////////////////////////////////////////////////////
	reg[31:0] hun_place;
	reg[31:0] ten_place;
	reg[31:0]one_place;
	////数据获取        
	always@(posedge clk or negedge rst)begin
	    if(!rst)
	        begin
	        hun_place = 0;
	        ten_place = 0;
	        one_place = 0;
	        spo_data = 8'd0;
	        heart_data = 8'd0;
	        delay_cnt1 = 40'd0;            
	        delay_cnt2 = 40'd0;            
	        end 
	    //////////////////////////////////////////////
	    else if(dataE == 8'h32)                                                  //当收到的数据为血氧时  
	    begin
	         if(dataA != 8'h4E)                                                      //不是null的数据  4E的ASCII码：N
	            begin
	            if(dataC == 8'h0D)                                                 //两位数     OD:回车
	                begin
	                    hun_place = 'd0; 
	                    ten_place = dataA - 'd48;
	                    one_place = dataB - 'd48;
	                    spo_data = hun_place*100 + ten_place*10 + one_place*1;
	                end
	             else if(dataD == 8'h0D)                                        //三位数
	                begin 
	                    hun_place = dataA - 'd48;
	                    ten_place = dataB - 'd48;
	                    one_place = dataC - 'd48;
	                    spo_data = hun_place*100 + ten_place*10 + one_place*1;
	                end
	            end 
	            else if(dataA == 8'h4E)
	            begin 
	                hun_place = 0;
	                ten_place = 0;
	                one_place = 0;
	                spo_data = 8'd0;
	            end
	     end
	     //////////////////////////////////////////////
	     else if(dataE == 8'h52)                                                  //当收到的数据为心率时 
	     begin
	         if(dataA != 8'h4E)                                                       //不是null的数据  
	            begin
	            if(dataC == 8'h0D)                                                  //两位数     
	                begin
	                    hun_place = 'd0; 
	                    ten_place = dataA - 'd48;
	                    one_place = dataB - 'd48;
	                    heart_data = hun_place*100 + ten_place*10 + one_place*1;
	                end
	             else if(dataD == 8'h0D)                                          //三位数
	                begin 
	                    hun_place = dataA - 'd48;
	                    ten_place = dataB - 'd48;
	                    one_place = dataC - 'd48;
	                    heart_data = hun_place*100 + ten_place*10 + one_place*1;
	                end
	            end 
	            else if(dataA == 8'h4E)
	            begin 
	                hun_place = 0;
	                ten_place = 0;
	                one_place = 0;
	                heart_data = 8'd0;
	            end
	     end                
	end	 
	////////////////////////////////////////////////////////////
	always @(posedge clk or negedge rst)begin
	   if(!rst)begin
		    cur_state <= SEND_SPO;
	        tx_go_flag <= 1'b0;
			type_flag <= 8'd0;
			rx_en <= 1'b0;   
			end
		else begin
		   case(cur_state)
			   SEND_SPO:begin
			       tx_go_flag <= 1'b1;
			       type_flag <= 8'd1;
			       rx_en <= 1'b1;
				   if(tx_sig)begin
					  cur_state <= WAIT_SPO;
					end
					else begin
					  cur_state <= SEND_SPO;
					end
			   end
			   WAIT_SPO:begin
			      tx_go_flag <= 1'b0;
			      type_flag <= 8'd0;
			      rx_en <= 1'b1;
			      if(pack_done)begin                                           //等几秒再发
			          cur_state <= WAIT_DELAY_SPO;
	                  tx_go_flag <= 1'b0;
	                  rx_en <= 1'b0;
	                  end			
					else begin
					  cur_state <= WAIT_SPO;
					end 
		        end
		        WAIT_DELAY_SPO:begin
			      tx_go_flag <= 1'b0;
			      type_flag <= 8'd0;
			      rx_en <= 1'b0;
			      if(delay_cnt1 >= T_Delay2)begin                     //等几秒再发
			          cur_state <= SEND_HEART;
	                  delay_cnt1 <= 1'b0;
	                  end			
					else begin
					  cur_state <= WAIT_DELAY_SPO;
					  delay_cnt1 <= delay_cnt1 +1'b1;
					end 
		        end
		        SEND_HEART:begin
			       tx_go_flag <= 1'b1;
			       type_flag <= 8'd2;
			       rx_en <= 1'b1;
				   if(tx_sig)begin
					  cur_state <= WAIT_HEART;
					end
					else begin
					  cur_state <= SEND_HEART;
					end
			   end
			   WAIT_HEART:begin
			      tx_go_flag <= 1'b0;
			      type_flag <= 8'd0;
			      rx_en <= 1'b1;
			      if(pack_done)begin
					   cur_state <= WAIT_DELAY_HEART;
					   tx_go_flag <= 1'b0;
					   rx_en <= 1'b0;
					end				
					else begin
					  cur_state <= WAIT_HEART;
					end 
		        end
		        WAIT_DELAY_HEART:begin
			      tx_go_flag <= 1'b0;
			      type_flag <= 8'd0;
			      rx_en <= 1'b0;
			      if(delay_cnt2 >= T_Delay2)begin                    //等几秒再发
			          cur_state <= SEND_SPO;
	                  delay_cnt2 <= 1'b0;
	                  end			
					else begin
					  cur_state <= WAIT_DELAY_HEART;
					  delay_cnt2 <= delay_cnt2 +1'b1;
					end 
		        end	    
	         default:
	         begin
	         cur_state <= SEND_SPO;	
	         tx_go_flag <= 1'b0;
	         type_flag <= 8'd0;
	         rx_en <= 1'b0;
	         end
			endcase
		end
	end
	uart_rx_heart uart_rx_heart2(
	   .sys_clk(clk),
	  .sys_rst_n(rst),
	  .uart_rxd(uart_rx_from_heart),
	  .rx_en(rx_en),
	  .uart_data(uart_data),
	  .uart_done(uart_done),
	  .uart_get(uart_get),
	  .pack_cnt(pack_cnt),
	  .pack_ing(pack_ing),
	  .pack_done(pack_done),
	  .pack_num(pack_num),
	  .recv_done(rx_sig),
	  .dataA(dataA),
	  .dataB(dataB),
	  .dataC(dataC),
	  .dataD(dataD),
	  .dataE(dataE));
	
	
	//---Module instantiation---
	uart_tx_data uart_tx_data1(
		.Clk(clk),
		.Reset_n(rst),
		.Tx_Go(tx_go_flag),
		.Trans_Done(tx_sig),
		.uart_tx(uart_tx_to_heart),
		.type_flag(type_flag));

endmodule    //heart_o2_top

